const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
function privateFiles(directory,state={}){fs.mkdirSync(directory,{recursive:true});const operations=[];const resolve=p=>{const result=path.resolve(directory,p);if(!result.startsWith(path.resolve(directory)+path.sep))throw Error('test-port path escaped');return result;};const before=(operation,p)=>{operations.push([operation,p]);if(state.fail?.(operation,p))throw Error('synthetic private storage failure');};return {directory,state,operations,protection:{excludedFromBackup:true,protected:true,location:'native-private'},uri:p=>'file://'+resolve(p),read:async p=>{before('read',p);return new Uint8Array(fs.readFileSync(resolve(p)));},writeNew:async(p,bytes)=>{before('write',p);const dest=resolve(p);fs.mkdirSync(path.dirname(dest),{recursive:true});fs.writeFileSync(dest,state.corruptWrite?.(p)?Buffer.from('synthetic partial write'):bytes,{flag:'wx'});},move:async(from,to)=>{before('move',to);const dest=resolve(to);if(fs.existsSync(dest))throw Error('test-port refuses overwrite');fs.mkdirSync(path.dirname(dest),{recursive:true});fs.renameSync(resolve(from),dest);},remove:async p=>{before('remove',p);fs.rmSync(resolve(p),{force:true});},exists:async p=>{before('exists',p);return fs.existsSync(resolve(p));},list:async dir=>{before('list',dir);const root=resolve(dir);if(!fs.existsSync(root))return [];return fs.readdirSync(root).filter(n=>fs.statSync(path.join(root,n)).isFile()).map(name=>({name,byteLength:fs.statSync(path.join(root,name)).size}));},sha256:async bytes=>{before('hash','');return crypto.createHash('sha256').update(bytes).digest('hex');}};}
module.exports={privateFiles};
